@startuml

class EBike {
  + frame : Frame
  + wheels : Wheel[]
  + driveSystem : DriveSystem
  + controller : Controller
}

class Frame {
  - material : string
}

class Wheel {}

class DriveSystem {
  + motor : Motor
}

class Motor {}

class Battery {
  + storedEnergy : double
}

class Controller {
  + state : String
  + controlBattery(battery : Battery) : void
  + commandDriveSystem(driveSystem : DriveSystem) : void
}

class BasicController extends Controller {}

class AdvancedController extends Controller {
  + estimateNextInspectionDate() : Date
}

EBike "1" *-- "1 frame" Frame
EBike "2" -- "*" Wheel
EBike "1" *-- "1 driveSystem" DriveSystem
DriveSystem "1" *-- "1 motor" Motor
EBike "0..1" *-- "1 battery" Battery
Controller "1" -- "1 basicController" BasicController
Controller "1" -- "1 advancedController" AdvancedController

@enduml

